Purpose: Lead Investigator: assess evidence

Expected response schema:
{
  "description": "An evidence assessment for the current investigation round.",
  "properties": {
    "action_id": {
      "type": "string"
    },
    "evidence_id": {
      "type": "string"
    },
    "links": {
      "items": {
        "properties": {
          "evidence_id": {
            "type": "string"
          },
          "hypothesis_id": {
            "type": "string"
          },
          "rationale": {
            "type": "string"
          },
          "relation": {
            "enum": [
              "supports",
              "contradicts"
            ]
          }
        },
        "type": "object"
      },
      "type": "array"
    },
    "outcome": {
      "enum": [
        "informative",
        "inconclusive"
      ]
    },
    "rationale": {
      "type": "string"
    },
    "status_updates": {
      "items": {
        "properties": {
          "hypothesis_id": {
            "type": "string"
          },
          "new_status": {
            "enum": [
              "active",
              "supported",
              "weakened",
              "refuted",
              "survived"
            ]
          },
          "rationale": {
            "type": "string"
          }
        },
        "type": "object"
      },
      "type": "array"
    }
  },
  "type": "object"
}
